"""Case-study outlines, one per project: three linked questions + suggested ArcGIS StoryMaps blocks + credited photos.

These are QUESTIONS and a plan. They never state findings — the answers come from the user's own analysis.
Photos are from Wikimedia Commons under the licences shown; keep the credit line next to each image.
"""
_T = "https://thumb.wikimedia.org/wikipedia/commons/thumb/"


def img(path, w, alt, credit, licence, page, role="inline"):
    return {"url": f"{_T}{path}/1920px-{w}", "alt": alt, "credit": credit, "licence": licence,
            "page": "https://commons.wikimedia.org/wiki/File:" + page, "role": role}


def q(label, title, text, how, show):
    return {"label": label, "title": title, "text": text, "how": how, "show": show}


